#include <iostream>
using namespace std;

int main() {
    int varsta;
    cout << "Introdu varsta: ";
    cin >> varsta;

    if (varsta >= 13 && varsta <= 19) {
        cout << "Esti adolescent!" << endl;
    } else {
        cout << "Nu esti adolescent." << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    char litera;
    cout << "Introdu o litera: ";
    cin >> litera;

    if (litera == 'a' || litera == 'e' || litera == 'i' || litera == 'o' || litera == 'u') {
        cout << "Este vocala!" << endl;
    } else {
        cout << "Este consoana." << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int nota;
    cout << "Introdu nota: ";
    cin >> nota;

    if (!(nota >= 5)) {
        cout << "Nota e sub 5 - ai picat!" << endl;
    }

    // Echivalent cu:
    if (nota < 5) {
        cout << "Nota e sub 5 - ai picat!" << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int varsta, bani;
    cout << "Varsta: "; cin >> varsta;
    cout << "Bani: "; cin >> bani;

    // Poti intra daca: ai peste 18 ani SAU (ai peste 12 ani SI ai bani pentru bilet)
    if (varsta >= 18 || (varsta >= 12 && bani >= 30)) {
        cout << "Poti intra la film!" << endl;
    } else {
        cout << "Nu poti intra." << endl;
    }

    return 0;
}
